var t=`0877-chingri-malai-curry`;var n=`world-0877`;var a=`BD`;var s=`south-asia`;var r=4;var o=39;var g={en:`Chingri Malai Curry`,ua:`Креветкове малаї-карі`};var l={en:`Chingri Malai Curry is a Bangladesh dish made with yellow onion, ginger-garlic paste, coconut milk, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Креветкове малаї-карі, страва кухні країни Бангладеш. Основні складники: жовта цибуля, імбирно-часникова паста, кокосове молоко, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,190,`g`],[`ginger-garlic-paste`,22,`g`],[`mustard-oil`,40,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`coconut-milk`,420,`ml`],[`tomato`,220,`g`],[`ground-cumin`,5,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`shrimp`,650,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,17,`g`]]}];var d={slug:t,id:n,country:`BD`,region:s,servings:4,minutes:39,title:g,text:l,steps:u};export{a as country,d as default,n as id,o as minutes,s as region,r as servings,t as slug,u as steps,l as text,g as title};